import { GoogleGenAI, GenerateContentResponse, Chat, Modality } from "@google/genai";

const GEMINI_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-2.5-flash-image';
const VIDEO_MODEL = 'veo-3.1-fast-generate-preview';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `You are "Lumina TCM Lab Agent", a scientific health researcher and holistic healer. 
Your goal is to explain TCM concepts using the scientific method: Observation, Hypothesis, and Intervention.

TONE & STYLE:
- Use clear, accessible language. Use emojis (🍎, 🧘‍♂️, 🍵, ⚡).
- Favor the scientific method: explain the "mechanism" of action clearly.
- Provide actionable health commitments.

REQUIRED JSON ARTIFACT SCHEMA (V4.0):
You MUST include this block at the end of diagnostic responses:
\`\`\`json
{
  "syndrome": {
    "name": "Syndrome Name",
    "hypothesis": "Hypothetical pathological explanation",
    "metrics": [
      { "label": "Energy Level", "value": 75, "sub": "Stable", "trend": [60, 65, 70, 75] }
    ]
  },
  "visualPrompts": {
    "imagePrompt": "A high quality close up photo of a healthy meal containing [ingredients] for [syndrome]",
    "videoPrompt": "A person demonstrating a simple slow breathing exercise for [syndrome]"
  },
  "regimen": {
    "actions": [
      {"id": "A1", "emoji": "🍵", "title": "Hydration Strategy", "description": "Specific tea or water routine"},
      {"id": "A2", "emoji": "🧘", "title": "Movement Lab", "description": "Specific exercise or posture"}
    ],
    "commitmentCount": 5
  }
}
\`\`\``;

let chatSession: Chat | null = null;

export async function createTCMChat(history?: any[]) {
  chatSession = ai.chats.create({
    model: GEMINI_MODEL,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.5,
      tools: [{ googleSearch: {} }],
    },
    history: history
  });
}

export async function generateHealthImage(prompt: string): Promise<string | null> {
  const localAi = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await localAi.models.generateContent({
    model: IMAGE_MODEL,
    contents: { parts: [{ text: prompt }] },
    config: { imageConfig: { aspectRatio: "1:1" } }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
  }
  return null;
}

export async function generateHealthVideo(prompt: string): Promise<string | null> {
  const localAi = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let operation = await localAi.models.generateVideos({
    model: VIDEO_MODEL,
    prompt: prompt,
    config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
  });

  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 8000));
    operation = await localAi.operations.getVideosOperation({ operation });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (downloadLink) {
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }
  return null;
}

export async function getTCMResponse(
  userMessage: string, 
  context: { organ: string; element: string; diagnostics?: string },
  imageBase64?: string,
  mimeType?: string
): Promise<{ text: string; data?: any; sources?: any[] }> {
  if (!chatSession) await createTCMChat();

  const parts: any[] = [];
  const telemetry = `[LAB OBSERVATION] 
Cycle: ${context.organ} (${context.element})
Sensors: ${context.diagnostics || 'Idle'}
---
`;
  parts.push({ text: telemetry + userMessage });

  if (imageBase64 && mimeType) {
    parts.push({ inlineData: { data: imageBase64, mimeType: mimeType } });
  }

  const result = await chatSession!.sendMessage({ message: parts });
  let fullText = result.text || "";
  const sources: any[] = [];
  if (result.candidates?.[0]?.groundingMetadata?.groundingChunks) {
    result.candidates[0].groundingMetadata.groundingChunks.forEach((c: any) => {
      if (c.web) sources.push({ uri: c.web.uri, title: c.web.title });
    });
  }

  let data = undefined;
  const jsonMatch = fullText.match(/```json([\s\S]*?)```/);
  if (jsonMatch) {
    try {
      data = JSON.parse(jsonMatch[1].trim());
      fullText = fullText.replace(/```json[\s\S]*?```/, '').trim();
    } catch (e) { console.error("JSON Error", e); }
  }

  return { text: fullText, data, sources };
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export async function speakResponse(text: string): Promise<void> {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `A friendly helpful lab researcher: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      }
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContext, 24000, 1);
      const source = outputAudioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(outputAudioContext.destination);
      source.start();
    }
  } catch (e) {
    const utterance = new SpeechSynthesisUtterance(text);
    window.speechSynthesis.speak(utterance);
  }
}

