import React, { useState, useEffect, useRef } from 'react';
import { 
  BeakerIcon,
  SparklesIcon,
  VideoCameraIcon,
  PhotoIcon,
  HeartIcon,
  ClockIcon,
  BoltIcon,
  CheckCircleIcon,
  MicrophoneIcon,
  PaperAirplaneIcon,
  TrashIcon,
  SpeakerWaveIcon,
  LinkIcon,
  ShieldCheckIcon,
  ExclamationTriangleIcon,
  KeyIcon,
  FaceSmileIcon
} from '@heroicons/react/24/outline';
import { 
  getTCMResponse, 
  createTCMChat, 
  speakResponse, 
  generateHealthImage, 
  generateHealthVideo 
} from '../services/gemini';
import { TCMVisualizer } from './TCMVisualizer';

const STORAGE_KEY = 'lumina_lab_data_v4';

const ORGAN_CLOCK = [
  { start: 1,  end: 3,  organ:'Liver',          element:'Wood',  emoji: '🌳' },
  { start: 3,  end: 5,  organ:'Lungs',          element:'Metal', emoji: '💨' },
  { start: 7,  end: 9,  organ:'Stomach',        element:'Earth', emoji: '🥣' },
  { start: 11, end: 13, organ:'Heart',          element:'Fire',  emoji: '❤️' },
  { start: 17, end: 19, organ:'Kidneys',        element:'Water', emoji: '🌊' }
];

export const TCMDashboard: React.FC = () => {
  const [messages, setMessages] = useState<any[]>([]);
  const [patternData, setPatternData] = useState<any>(null);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [commitments, setCommitments] = useState<string[]>([]);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [hasVeoKey, setHasVeoKey] = useState(false);
  const [generatingVisuals, setGeneratingVisuals] = useState(false);
  const [prescribedImage, setPrescribedImage] = useState<string | null>(null);
  const [prescribedVideo, setPrescribedVideo] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      const hasKey = await (window as any).aistudio.hasSelectedApiKey();
      setHasVeoKey(hasKey);
    };
    checkKey();

    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      const parsed = JSON.parse(stored);
      setMessages(parsed.messages || []);
      setPatternData(parsed.patternData || null);
      setCommitments(parsed.commitments || []);
    }
    createTCMChat();
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ messages, patternData, commitments }));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, commitments]);

  const handleOpenKeyDialog = async () => {
    await (window as any).aistudio.openSelectKey();
    setHasVeoKey(true);
  };

  const handleSend = async () => {
    if (!input.trim() && !imagePreview) return;

    const txt = input;
    const img = imagePreview;
    setInput('');
    setImagePreview(null);
    setIsTyping(true);
    setPrescribedImage(null);
    setPrescribedVideo(null);

    setMessages(prev => [...prev, { role: 'user', text: txt, image: img }]);

    const h = new Date().getHours();
    const active = ORGAN_CLOCK.find(o => (h >= o.start && h < o.end)) || ORGAN_CLOCK[0];

    try {
      const response = await getTCMResponse(txt, { organ: active.organ, element: active.element }, img?.split(',')[1], 'image/png');
      setMessages(prev => [...prev, { role: 'ai', text: response.text, sources: response.sources }]);
      if (response.data) {
        setPatternData(response.data);
        // Automatically start generating visuals for the plan
        handleGenerateVisuals(response.data.visualPrompts);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  const handleGenerateVisuals = async (prompts: any) => {
    if (!prompts) return;
    setGeneratingVisuals(true);
    try {
      if (prompts.imagePrompt) {
        const img = await generateHealthImage(prompts.imagePrompt);
        setPrescribedImage(img);
      }
      if (prompts.videoPrompt && hasVeoKey) {
        const vid = await generateHealthVideo(prompts.videoPrompt);
        setPrescribedVideo(vid);
      }
    } catch (e) {
      console.error("Visual generation failed", e);
    } finally {
      setGeneratingVisuals(false);
    }
  };

  const commitToTask = (taskId: string) => {
    if (!commitments.includes(taskId)) {
      setCommitments(prev => [...prev, taskId]);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 text-slate-900 overflow-hidden dyslexic-friendly">
      {/* Header */}
      <header className="h-14 bg-white border-b border-slate-200 flex items-center justify-between px-6 shrink-0 z-50 lab-shadow">
        <div className="flex items-center gap-3">
          <div className="p-1.5 bg-teal-50 rounded-lg">
            <BeakerIcon className="w-5 h-5 text-teal-600" />
          </div>
          <h1 className="font-bold text-lg tracking-tight">Lumina <span className="text-teal-600">Health Lab</span></h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden sm:flex items-center gap-2">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Daily Progress</span>
            <div className="w-32 h-2 bg-slate-100 rounded-full overflow-hidden border border-slate-200">
               <div className="h-full bg-teal-500 transition-all duration-500" style={{ width: `${(commitments.length / 5) * 100}%` }}></div>
            </div>
            <span className="text-xs font-bold text-teal-600">{commitments.length}/5</span>
          </div>

          {!hasVeoKey && (
            <button 
              onClick={handleOpenKeyDialog}
              className="flex items-center gap-2 px-3 py-1 bg-amber-50 text-amber-700 border border-amber-200 rounded-full text-[10px] font-bold uppercase transition-all hover:bg-amber-100"
            >
              <KeyIcon className="w-3 h-3" /> Enable Video Lab
            </button>
          )}

          <button onClick={() => { localStorage.removeItem(STORAGE_KEY); setMessages([]); setPatternData(null); setCommitments([]); }} className="p-2 text-slate-400 hover:text-rose-500 transition-colors">
            <TrashIcon className="w-5 h-5" />
          </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row overflow-hidden">
        {/* Left Panel: Lab Observation & Visualization */}
        <div className="flex-1 overflow-y-auto p-4 md:p-6 bg-lab-grid space-y-6">
          {/* Observation Summary */}
          <section className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="p-5 bg-white rounded-2xl lab-shadow border border-slate-200 flex flex-col gap-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Hypothesis Lab</span>
              <h3 className="text-lg font-bold text-slate-800">{patternData?.syndrome?.name || "Awaiting Input..."}</h3>
              <p className="text-xs text-slate-500 leading-relaxed mt-1">
                {patternData?.syndrome?.hypothesis || "Please describe your current state or upload a photo to start the scientific analysis."}
              </p>
            </div>
            <div className="p-5 bg-white rounded-2xl lab-shadow border border-slate-200 flex items-center justify-around">
               {ORGAN_CLOCK.map(o => (
                 <div key={o.organ} className={`flex flex-col items-center gap-1 transition-all ${new Date().getHours() >= o.start && new Date().getHours() < o.end ? 'scale-110' : 'opacity-30'}`}>
                   <span className="text-xl">{o.emoji}</span>
                   <span className="text-[8px] font-bold uppercase">{o.organ}</span>
                 </div>
               ))}
            </div>
          </section>

          {/* Visual Evidence Area */}
          <section className="bg-white rounded-[2.5rem] lab-shadow border border-slate-200 overflow-hidden">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <SparklesIcon className="w-4 h-4 text-teal-600" />
                <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Prescribed Visuals</span>
              </div>
              {generatingVisuals && (
                <div className="flex items-center gap-2 text-teal-600 text-[10px] font-bold animate-pulse">
                  <ClockIcon className="w-3 h-3" /> Synthesis in Progress...
                </div>
              )}
            </div>
            <div className="p-6 grid grid-cols-1 lg:grid-cols-2 gap-6 min-h-[300px]">
              {prescribedImage ? (
                <div className="space-y-3 group">
                  <img src={prescribedImage} className="w-full h-48 object-cover rounded-2xl border border-slate-200 shadow-sm transition-transform group-hover:scale-[1.02]" alt="Plan Image" />
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Scientific Visualization</span>
                    <button className="text-[10px] font-bold text-teal-600 flex items-center gap-1">
                       <CheckCircleIcon className="w-4 h-4" /> Save to Log
                    </button>
                  </div>
                </div>
              ) : (
                <div className="h-48 rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300 gap-2">
                  <PhotoIcon className="w-8 h-8" />
                  <span className="text-xs font-medium">Image prescriptions appear here</span>
                </div>
              )}

              {prescribedVideo ? (
                <div className="space-y-3 group">
                  <video src={prescribedVideo} controls className="w-full h-48 bg-black rounded-2xl border border-slate-200 shadow-sm" />
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Mindfulness Video</span>
                    <button className="text-[10px] font-bold text-rose-600 flex items-center gap-1">
                       <HeartIcon className="w-4 h-4" /> Heart Resonated
                    </button>
                  </div>
                </div>
              ) : (
                <div className="h-48 rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300 gap-2">
                  <VideoCameraIcon className="w-8 h-8" />
                  <span className="text-xs font-medium">{hasVeoKey ? "Video prescriptions appear here" : "Enable Video Lab above"}</span>
                </div>
              )}
            </div>
          </section>

          {/* Plan Commitment Section */}
          <section className="space-y-4">
             <div className="flex items-center gap-2">
                <CheckCircleIcon className="w-5 h-5 text-teal-600" />
                <h4 className="text-sm font-bold text-slate-700">Health Commitment Matrix</h4>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {patternData?.regimen?.actions?.map((action: any) => (
                  <button 
                    key={action.id}
                    onClick={() => commitToTask(action.id)}
                    className={`p-4 rounded-2xl border transition-all text-left flex items-start gap-4 ${
                      commitments.includes(action.id) 
                      ? 'bg-teal-50 border-teal-200 shadow-sm opacity-60' 
                      : 'bg-white border-slate-200 hover:border-teal-400 hover:shadow-md'
                    }`}
                  >
                    <span className="text-3xl">{action.emoji}</span>
                    <div className="flex-1">
                      <div className="flex items-center justify-between">
                         <h5 className={`font-bold text-sm ${commitments.includes(action.id) ? 'text-teal-700 line-through' : 'text-slate-800'}`}>
                           {action.title}
                         </h5>
                         {commitments.includes(action.id) && <CheckCircleIcon className="w-4 h-4 text-teal-500" />}
                      </div>
                      <p className="text-xs text-slate-500 mt-0.5">{action.description}</p>
                    </div>
                  </button>
                ))}
                {!patternData && <div className="col-span-full py-12 text-center text-slate-300 text-xs italic">Awaiting intervention plan...</div>}
             </div>
          </section>

          {/* Traditional Visualization */}
          <div className="h-80 bg-white rounded-[2.5rem] lab-shadow border border-slate-200 p-6 overflow-hidden">
             <TCMVisualizer data={patternData} view="DATA" />
          </div>
        </div>

        {/* Right Panel: Chat & Log */}
        <div className="w-full md:w-96 flex flex-col bg-white border-l border-slate-200 shadow-xl z-20">
          <div className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-thin">
            {messages.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4 opacity-50">
                <FaceSmileIcon className="w-16 h-16" />
                <p className="text-sm font-medium">Hello! I'm your Lab Assistant. Describe your symptoms to begin.</p>
              </div>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} gap-2`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-xs leading-relaxed shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-teal-600 text-white rounded-tr-none' 
                  : 'bg-slate-100 text-slate-800 rounded-tl-none border border-slate-200'
                }`}>
                  {m.image && <img src={m.image} alt="User Input" className="mb-3 rounded-lg max-h-40 w-full object-cover border border-white/20" />}
                  <div className="whitespace-pre-wrap">{m.text}</div>
                  {m.sources?.length > 0 && (
                    <div className="mt-4 pt-3 border-t border-slate-200/50 flex flex-wrap gap-2">
                       {m.sources.map((s: any, idx: number) => (
                         <a key={idx} href={s.uri} target="_blank" rel="noopener noreferrer" className="px-2 py-1 bg-white/50 rounded-lg text-[8px] font-bold text-slate-500 flex items-center gap-1 hover:bg-white hover:text-teal-600 transition-all">
                           <LinkIcon className="w-2 h-2" /> {s.title}
                         </a>
                       ))}
                    </div>
                  )}
                </div>
                {m.role === 'ai' && (
                  <button onClick={() => speakResponse(m.text)} className="p-1.5 text-slate-400 hover:text-teal-500 transition-colors">
                    <SpeakerWaveIcon className="w-4 h-4" />
                  </button>
                )}
              </div>
            ))}
            {isTyping && (
              <div className="flex gap-1.5 p-3 bg-slate-50 rounded-xl w-fit border border-slate-200">
                <div className="w-2 h-2 rounded-full bg-teal-300 animate-bounce"></div>
                <div className="w-2 h-2 rounded-full bg-teal-400 animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-2 h-2 rounded-full bg-teal-500 animate-bounce [animation-delay:0.4s]"></div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          <div className="p-4 border-t border-slate-200 bg-slate-50/80 backdrop-blur-md">
            {imagePreview && (
              <div className="mb-3 relative w-16 h-16 group">
                 <img src={imagePreview} className="w-full h-full object-cover rounded-xl border-2 border-teal-500 shadow-md" alt="Preview" />
                 <button onClick={() => setImagePreview(null)} className="absolute -top-2 -right-2 bg-rose-500 text-white p-1 rounded-full shadow-lg">
                    <TrashIcon className="w-3 h-3" />
                 </button>
              </div>
            )}
            <div className="flex items-center gap-2">
              <button 
                onClick={() => fileInputRef.current?.click()} 
                className="p-3 bg-white border border-slate-200 rounded-xl text-slate-400 hover:text-teal-500 hover:border-teal-200 transition-all shadow-sm"
              >
                <PhotoIcon className="w-5 h-5" />
              </button>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) {
                  const r = new FileReader();
                  r.onload = () => setImagePreview(r.result as string);
                  r.readAsDataURL(f);
                }
              }} />
              <input 
                type="text" 
                value={input} 
                onChange={(e) => setInput(e.target.value)} 
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask your assistant..." 
                className="flex-1 px-4 py-3 bg-white border border-slate-200 rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-teal-500/20 shadow-inner"
              />
              <button onClick={handleSend} className="p-3 bg-teal-600 text-white rounded-xl shadow-lg shadow-teal-600/20 hover:bg-teal-500 active:scale-95 transition-all">
                <PaperAirplaneIcon className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

